import{i as e,r as t,s as n,t as r}from"./app-JQzCrjpL.js";var i=JSON.parse(`{"path":"/guide/configuration-and-lifecycle/","title":"Конфигурация и жизненный цикл приложения","lang":"ru-RU","frontmatter":{"prev":"/guide/resty/best-practices.md","next":"/guide/configuration-and-lifecycle/tests.md"},"git":{"updatedTime":1792184190000,"contributors":[{"name":"Danil Chugaev","username":"","email":"danilchugaev@mail.ru","commits":1}],"changelog":[{"hash":"6265ebd7120ee6b0249cd9897366340967e3fc47","time":1792184190000,"email":"danilchugaev@mail.ru","author":"Danil Chugaev","message":"fixes"}]},"filePathRelative":"guide/configuration-and-lifecycle/README.md"}`),a={name:`README.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="конфигурация-и-жизненныи-цикл-приложения" tabindex="-1"><a class="header-anchor" href="#конфигурация-и-жизненныи-цикл-приложения"><span>Конфигурация и жизненный цикл приложения</span></a></h1><h2 id="цель-урока" tabindex="-1"><a class="header-anchor" href="#цель-урока"><span>Цель урока</span></a></h2><p>Научиться получать настройки Task Manager API из переменных окружения и локального <code>.env</code>, проверять конфигурацию при старте, запускать HTTP-сервер с таймаутами, корректно обрабатывать <code>SIGINT</code> и <code>SIGTERM</code>, выполнять graceful shutdown и закрывать зависимости приложения.</p><p>До этого момента значения вроде <code>:8080</code> и адреса внешнего API можно было писать прямо в примере. В настоящем приложении среда меняется: локальная разработка, тесты, Docker и production используют разные адреса, токены и пути. Такие значения становятся конфигурацией, а не частью исходного кода.</p><h2 id="двенадцатифакторныи-принцип" tabindex="-1"><a class="header-anchor" href="#двенадцатифакторныи-принцип"><span>Двенадцатифакторный принцип</span></a></h2><p>Конфигурация зависит от окружения и должна быть отделена от кода:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">код:            как работает приложение</span>
<span class="line">переменные env: где слушать порт, куда подключаться, какой timeout использовать</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>Не храните в Git секреты, production-адреса и пароли. Код читает значения из окружения, а платформа запуска — shell, Docker Compose, CI или hosting — передаёт их приложению.</p><h2 id="структура-конфигурации" tabindex="-1"><a class="header-anchor" href="#структура-конфигурации"><span>Структура конфигурации</span></a></h2><p>Соберём все настройки в один тип:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">type</span> Config <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">	HTTPAddress        <span class="token builtin">string</span></span>
<span class="line">	ShutdownTimeout    time<span class="token punctuation">.</span>Duration</span>
<span class="line">	PriorityServiceURL <span class="token builtin">string</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Для текущей версии Task Manager нужны:</p><table><thead><tr><th>Переменная</th><th>Назначение</th><th>Значение по умолчанию</th></tr></thead><tbody><tr><td><code>HTTP_ADDRESS</code></td><td>адрес HTTP-сервера</td><td><code>:8080</code></td></tr><tr><td><code>SHUTDOWN_TIMEOUT</code></td><td>максимум времени на graceful shutdown</td><td><code>10s</code></td></tr><tr><td><code>PRIORITY_SERVICE_URL</code></td><td>базовый URL внешнего сервиса приоритетов</td><td>обязательна</td></tr></tbody></table><p>Позже сюда добавятся адрес PostgreSQL и учётные данные. Не создавайте глобальные переменные для отдельных значений: один <code>Config</code> легче валидировать и передавать при сборке зависимостей.</p><h2 id="переменные-окружения" tabindex="-1"><a class="header-anchor" href="#переменные-окружения"><span>Переменные окружения</span></a></h2><p>Стандартный пакет <code>os</code> предоставляет два основных способа чтения env:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">value <span class="token operator">:=</span> os<span class="token punctuation">.</span><span class="token function">Getenv</span><span class="token punctuation">(</span><span class="token string">&quot;HTTP_ADDRESS&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><code>Getenv</code> возвращает пустую строку и для отсутствующей переменной, и для явно заданного пустого значения. Если нужно различать эти сценарии, используйте <code>LookupEnv</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">value<span class="token punctuation">,</span> exists <span class="token operator">:=</span> os<span class="token punctuation">.</span><span class="token function">LookupEnv</span><span class="token punctuation">(</span><span class="token string">&quot;PRIORITY_SERVICE_URL&quot;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> <span class="token operator">!</span>exists <span class="token operator">||</span> strings<span class="token punctuation">.</span><span class="token function">TrimSpace</span><span class="token punctuation">(</span>value<span class="token punctuation">)</span> <span class="token operator">==</span> <span class="token string">&quot;&quot;</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> Config<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> errors<span class="token punctuation">.</span><span class="token function">New</span><span class="token punctuation">(</span><span class="token string">&quot;PRIORITY_SERVICE_URL обязателен&quot;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Для необязательных переменных удобно сделать helper:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">envOrDefault</span><span class="token punctuation">(</span>key<span class="token punctuation">,</span> fallback <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token builtin">string</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">if</span> value <span class="token operator">:=</span> strings<span class="token punctuation">.</span><span class="token function">TrimSpace</span><span class="token punctuation">(</span>os<span class="token punctuation">.</span><span class="token function">Getenv</span><span class="token punctuation">(</span>key<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> value <span class="token operator">!=</span> <span class="token string">&quot;&quot;</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> value</span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">return</span> fallback</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Пустое значение здесь означает «использовать fallback». Для обязательных секретов или URL используйте отдельную проверку, а не fallback, который скроет ошибку конфигурации.</p><h2 id="локальныи-env" tabindex="-1"><a class="header-anchor" href="#локальныи-env"><span>Локальный <code>.env</code></span></a></h2><p>ОС и production-платформа не читают <code>.env</code> автоматически. Для локальной разработки подключим <code>github.com/joho/godotenv</code>:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line">go get github.com/joho/godotenv</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>В <code>main</code> загрузите файл до чтения конфигурации:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">if</span> err <span class="token operator">:=</span> godotenv<span class="token punctuation">.</span><span class="token function">Load</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token operator">&amp;&amp;</span> <span class="token operator">!</span>errors<span class="token punctuation">.</span><span class="token function">Is</span><span class="token punctuation">(</span>err<span class="token punctuation">,</span> os<span class="token punctuation">.</span>ErrNotExist<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;загрузить .env: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Если <code>.env</code> отсутствует, это не ошибка: переменные могут быть переданы из shell, Docker или CI. Если файл есть, но прочитать его не удалось, запуск нужно остановить.</p><p>Создайте в репозитории шаблон <code>.env.example</code>, но не добавляйте сам <code>.env</code> в Git:</p><div class="language-dotenv line-numbers-mode" data-highlighter="prismjs" data-ext="dotenv"><pre><code class="language-dotenv"><span class="line"># Локальный HTTP-сервер.</span>
<span class="line">HTTP_ADDRESS=:8080</span>
<span class="line"></span>
<span class="line"># Время на завершение активных HTTP-запросов после SIGINT/SIGTERM.</span>
<span class="line">SHUTDOWN_TIMEOUT=10s</span>
<span class="line"></span>
<span class="line"># Адрес тестового или локального внешнего сервиса.</span>
<span class="line">PRIORITY_SERVICE_URL=http://localhost:8090</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Добавьте в <code>.gitignore</code>:</p><div class="language-gitignore line-numbers-mode" data-highlighter="prismjs" data-ext="gitignore"><pre><code class="language-gitignore"><span class="line"><span class="token entry string">.env</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><code>godotenv.Load</code> не должен перезаписывать значения, которые уже передала среда. Поэтому shell и production-платформа имеют приоритет над локальным <code>.env</code>.</p><h2 id="разбор-и-валидация-конфигурации" tabindex="-1"><a class="header-anchor" href="#разбор-и-валидация-конфигурации"><span>Разбор и валидация конфигурации</span></a></h2><p>Значения env — всегда строки. Сразу преобразуйте и проверьте их при старте, а не внутри HTTP handler:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">Load</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">(</span>Config<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	shutdownTimeout<span class="token punctuation">,</span> err <span class="token operator">:=</span> time<span class="token punctuation">.</span><span class="token function">ParseDuration</span><span class="token punctuation">(</span><span class="token function">envOrDefault</span><span class="token punctuation">(</span><span class="token string">&quot;SHUTDOWN_TIMEOUT&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;10s&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> Config<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;SHUTDOWN_TIMEOUT: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">if</span> shutdownTimeout <span class="token operator">&lt;=</span> <span class="token number">0</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> Config<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> errors<span class="token punctuation">.</span><span class="token function">New</span><span class="token punctuation">(</span><span class="token string">&quot;SHUTDOWN_TIMEOUT должен быть больше нуля&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	priorityServiceURL <span class="token operator">:=</span> strings<span class="token punctuation">.</span><span class="token function">TrimSpace</span><span class="token punctuation">(</span>os<span class="token punctuation">.</span><span class="token function">Getenv</span><span class="token punctuation">(</span><span class="token string">&quot;PRIORITY_SERVICE_URL&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> priorityServiceURL <span class="token operator">==</span> <span class="token string">&quot;&quot;</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> Config<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> errors<span class="token punctuation">.</span><span class="token function">New</span><span class="token punctuation">(</span><span class="token string">&quot;PRIORITY_SERVICE_URL обязателен&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	endpoint<span class="token punctuation">,</span> err <span class="token operator">:=</span> url<span class="token punctuation">.</span><span class="token function">ParseRequestURI</span><span class="token punctuation">(</span>priorityServiceURL<span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token operator">||</span> endpoint<span class="token punctuation">.</span>Scheme <span class="token operator">==</span> <span class="token string">&quot;&quot;</span> <span class="token operator">||</span> endpoint<span class="token punctuation">.</span>Host <span class="token operator">==</span> <span class="token string">&quot;&quot;</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> Config<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> errors<span class="token punctuation">.</span><span class="token function">New</span><span class="token punctuation">(</span><span class="token string">&quot;PRIORITY_SERVICE_URL должен быть абсолютным URL&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">return</span> Config<span class="token punctuation">{</span></span>
<span class="line">		HTTPAddress<span class="token punctuation">:</span>        <span class="token function">envOrDefault</span><span class="token punctuation">(</span><span class="token string">&quot;HTTP_ADDRESS&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;:8080&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">		ShutdownTimeout<span class="token punctuation">:</span>    shutdownTimeout<span class="token punctuation">,</span></span>
<span class="line">		PriorityServiceURL<span class="token punctuation">:</span> strings<span class="token punctuation">.</span><span class="token function">TrimRight</span><span class="token punctuation">(</span>priorityServiceURL<span class="token punctuation">,</span> <span class="token string">&quot;/&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">	<span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Проверка <code>url.ParseRequestURI</code> и полей <code>Scheme</code>/<code>Host</code> предотвращает ошибку, когда приложение запускается с <code>priority-service:8090</code> без <code>http://</code>. Не логируйте весь <code>Config</code> бездумно: будущие поля могут содержать пароль или token.</p><h2 id="тестирование-load" tabindex="-1"><a class="header-anchor" href="#тестирование-load"><span>Тестирование <code>Load</code></span></a></h2><p>Конфигурация — обычная логика, поэтому её надо тестировать. Не меняйте настоящий env процесса в параллельных тестах. Передайте функцию чтения как зависимость или используйте <code>t.Setenv</code> в непараллельных тестах:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">TestLoadInvalidShutdownTimeout</span><span class="token punctuation">(</span>t <span class="token operator">*</span>testing<span class="token punctuation">.</span>T<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	t<span class="token punctuation">.</span><span class="token function">Setenv</span><span class="token punctuation">(</span><span class="token string">&quot;PRIORITY_SERVICE_URL&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;https://priority.example.com&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	t<span class="token punctuation">.</span><span class="token function">Setenv</span><span class="token punctuation">(</span><span class="token string">&quot;SHUTDOWN_TIMEOUT&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;пять секунд&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	<span class="token boolean">_</span><span class="token punctuation">,</span> err <span class="token operator">:=</span> <span class="token function">Load</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">==</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		t<span class="token punctuation">.</span><span class="token function">Fatal</span><span class="token punctuation">(</span><span class="token string">&quot;Load не вернул ошибку&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>t.Setenv</code> сам восстановит значение после теста. Не вызывайте <code>t.Parallel</code> в тестах, которые используют <code>t.Setenv</code>: переменные окружения принадлежат всему процессу.</p><h2 id="сборка-зависимостеи-в-main" tabindex="-1"><a class="header-anchor" href="#сборка-зависимостеи-в-main"><span>Сборка зависимостей в <code>main</code></span></a></h2><p><code>main</code> отвечает за порядок старта: загрузить локальный <code>.env</code>, прочитать config, собрать logger и зависимости, затем запустить сервер.</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">run</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token builtin">error</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">:=</span> godotenv<span class="token punctuation">.</span><span class="token function">Load</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token operator">&amp;&amp;</span> <span class="token operator">!</span>errors<span class="token punctuation">.</span><span class="token function">Is</span><span class="token punctuation">(</span>err<span class="token punctuation">,</span> os<span class="token punctuation">.</span>ErrNotExist<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;загрузить .env: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	config<span class="token punctuation">,</span> err <span class="token operator">:=</span> config<span class="token punctuation">.</span><span class="token function">Load</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;конфигурация: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	logger <span class="token operator">:=</span> slog<span class="token punctuation">.</span><span class="token function">New</span><span class="token punctuation">(</span>slog<span class="token punctuation">.</span><span class="token function">NewJSONHandler</span><span class="token punctuation">(</span>os<span class="token punctuation">.</span>Stdout<span class="token punctuation">,</span> <span class="token boolean">nil</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">	priorityClient <span class="token operator">:=</span> priorityclient<span class="token punctuation">.</span><span class="token function">New</span><span class="token punctuation">(</span>config<span class="token punctuation">.</span>PriorityServiceURL<span class="token punctuation">,</span> <span class="token boolean">nil</span><span class="token punctuation">)</span></span>
<span class="line">	store <span class="token operator">:=</span> store<span class="token punctuation">.</span><span class="token function">NewTaskStore</span><span class="token punctuation">(</span>logger<span class="token punctuation">)</span></span>
<span class="line">	service <span class="token operator">:=</span> taskservice<span class="token punctuation">.</span><span class="token function">New</span><span class="token punctuation">(</span>store<span class="token punctuation">,</span> priorityClient<span class="token punctuation">)</span></span>
<span class="line">	api <span class="token operator">:=</span> ginapi<span class="token punctuation">.</span><span class="token function">New</span><span class="token punctuation">(</span>service<span class="token punctuation">,</span> logger<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	server <span class="token operator">:=</span> <span class="token function">newServer</span><span class="token punctuation">(</span>config<span class="token punctuation">.</span>HTTPAddress<span class="token punctuation">,</span> api<span class="token punctuation">.</span><span class="token function">Router</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">return</span> <span class="token function">serve</span><span class="token punctuation">(</span>server<span class="token punctuation">,</span> config<span class="token punctuation">.</span>ShutdownTimeout<span class="token punctuation">,</span> logger<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">:=</span> <span class="token function">run</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		slog<span class="token punctuation">.</span><span class="token function">Error</span><span class="token punctuation">(</span><span class="token string">&quot;приложение завершилось с ошибкой&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;err&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">		os<span class="token punctuation">.</span><span class="token function">Exit</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>main</code> — подходящее место для <code>os.Exit</code>, потому что это граница процесса. В library-коде возвращайте ошибки, а не завершайте процесс самостоятельно: так код можно тестировать и переиспользовать.</p><h2 id="http-server-и-защитные-таимауты" tabindex="-1"><a class="header-anchor" href="#http-server-и-защитные-таимауты"><span>HTTP server и защитные таймауты</span></a></h2><p>Не используйте <code>router.Run()</code> в production-сборке: он не даёт централизованно задать <code>http.Server</code>. Создайте сервер явно:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">newServer</span><span class="token punctuation">(</span>address <span class="token builtin">string</span><span class="token punctuation">,</span> handler http<span class="token punctuation">.</span>Handler<span class="token punctuation">)</span> <span class="token operator">*</span>http<span class="token punctuation">.</span>Server <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> <span class="token operator">&amp;</span>http<span class="token punctuation">.</span>Server<span class="token punctuation">{</span></span>
<span class="line">		Addr<span class="token punctuation">:</span>              address<span class="token punctuation">,</span></span>
<span class="line">		Handler<span class="token punctuation">:</span>           handler<span class="token punctuation">,</span></span>
<span class="line">		ReadHeaderTimeout<span class="token punctuation">:</span> <span class="token number">5</span> <span class="token operator">*</span> time<span class="token punctuation">.</span>Second<span class="token punctuation">,</span></span>
<span class="line">		ReadTimeout<span class="token punctuation">:</span>       <span class="token number">15</span> <span class="token operator">*</span> time<span class="token punctuation">.</span>Second<span class="token punctuation">,</span></span>
<span class="line">		WriteTimeout<span class="token punctuation">:</span>      <span class="token number">15</span> <span class="token operator">*</span> time<span class="token punctuation">.</span>Second<span class="token punctuation">,</span></span>
<span class="line">		IdleTimeout<span class="token punctuation">:</span>       <span class="token number">60</span> <span class="token operator">*</span> time<span class="token punctuation">.</span>Second<span class="token punctuation">,</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>Таймаут</th><th>Защищает от</th></tr></thead><tbody><tr><td><code>ReadHeaderTimeout</code></td><td>очень медленной передачи заголовков</td></tr><tr><td><code>ReadTimeout</code></td><td>слишком долгого чтения всего запроса</td></tr><tr><td><code>WriteTimeout</code></td><td>слишком долгой записи ответа</td></tr><tr><td><code>IdleTimeout</code></td><td>бесконечного удержания неактивного keep-alive соединения</td></tr></tbody></table><p>Значения зависят от продукта: например, для долгого скачивания или streaming нужны другие правила. Эти безопасные стартовые значения не являются универсальной нормой.</p><h2 id="сигналы-процесса" tabindex="-1"><a class="header-anchor" href="#сигналы-процесса"><span>Сигналы процесса</span></a></h2><p>При Ctrl+C терминал обычно отправляет процессу <code>SIGINT</code>; Docker и оркестраторы обычно используют <code>SIGTERM</code>. В обоих случаях приложение должно перестать принимать новые запросы и завершить активные в ограниченное время.</p><p><code>signal.NotifyContext</code> создаёт context, который отменяется при нужном сигнале:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">rootCtx<span class="token punctuation">,</span> stop <span class="token operator">:=</span> signal<span class="token punctuation">.</span><span class="token function">NotifyContext</span><span class="token punctuation">(</span>context<span class="token punctuation">.</span><span class="token function">Background</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> os<span class="token punctuation">.</span>Interrupt<span class="token punctuation">,</span> syscall<span class="token punctuation">.</span>SIGTERM<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">defer</span> <span class="token function">stop</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token operator">&lt;-</span>rootCtx<span class="token punctuation">.</span><span class="token function">Done</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Вызов <code>stop</code> важен: он освобождает ресурсы, связанные с получением сигналов, и возвращает стандартное поведение сигнала после выхода.</p><h2 id="graceful-shutdown" tabindex="-1"><a class="header-anchor" href="#graceful-shutdown"><span>Graceful shutdown</span></a></h2><p><code>server.Shutdown(ctx)</code>:</p><ol><li>закрывает listener — новые соединения и запросы больше не принимаются;</li><li>ждёт завершения активных handler;</li><li>возвращает ошибку, если context завершения истёк.</li></ol><p>Не используйте <code>server.Close()</code> как обычный путь остановки: он немедленно обрывает активные соединения. <code>Close</code> может быть аварийным fallback после истечения timeout, но не заменяет <code>Shutdown</code>.</p><p>Запустим <code>ListenAndServe</code> в goroutine и дождёмся сигнала:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">serve</span><span class="token punctuation">(</span>server <span class="token operator">*</span>http<span class="token punctuation">.</span>Server<span class="token punctuation">,</span> shutdownTimeout time<span class="token punctuation">.</span>Duration<span class="token punctuation">,</span> logger <span class="token operator">*</span>slog<span class="token punctuation">.</span>Logger<span class="token punctuation">)</span> <span class="token builtin">error</span> <span class="token punctuation">{</span></span>
<span class="line">	serverErrors <span class="token operator">:=</span> <span class="token function">make</span><span class="token punctuation">(</span><span class="token keyword">chan</span> <span class="token builtin">error</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">go</span> <span class="token keyword">func</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		serverErrors <span class="token operator">&lt;-</span> server<span class="token punctuation">.</span><span class="token function">ListenAndServe</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	rootCtx<span class="token punctuation">,</span> stop <span class="token operator">:=</span> signal<span class="token punctuation">.</span><span class="token function">NotifyContext</span><span class="token punctuation">(</span>context<span class="token punctuation">.</span><span class="token function">Background</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> os<span class="token punctuation">.</span>Interrupt<span class="token punctuation">,</span> syscall<span class="token punctuation">.</span>SIGTERM<span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">defer</span> <span class="token function">stop</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">select</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">case</span> err <span class="token operator">:=</span> <span class="token operator">&lt;-</span>serverErrors<span class="token punctuation">:</span></span>
<span class="line">		<span class="token keyword">if</span> <span class="token operator">!</span>errors<span class="token punctuation">.</span><span class="token function">Is</span><span class="token punctuation">(</span>err<span class="token punctuation">,</span> http<span class="token punctuation">.</span>ErrServerClosed<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">			<span class="token keyword">return</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;HTTP-сервер: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">		<span class="token punctuation">}</span></span>
<span class="line">		<span class="token keyword">return</span> <span class="token boolean">nil</span></span>
<span class="line">	<span class="token keyword">case</span> <span class="token operator">&lt;-</span>rootCtx<span class="token punctuation">.</span><span class="token function">Done</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">		logger<span class="token punctuation">.</span><span class="token function">Info</span><span class="token punctuation">(</span><span class="token string">&quot;начато корректное завершение&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;signal&quot;</span><span class="token punctuation">,</span> rootCtx<span class="token punctuation">.</span><span class="token function">Err</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	shutdownCtx<span class="token punctuation">,</span> cancel <span class="token operator">:=</span> context<span class="token punctuation">.</span><span class="token function">WithTimeout</span><span class="token punctuation">(</span>context<span class="token punctuation">.</span><span class="token function">Background</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> shutdownTimeout<span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">defer</span> <span class="token function">cancel</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">:=</span> server<span class="token punctuation">.</span><span class="token function">Shutdown</span><span class="token punctuation">(</span>shutdownCtx<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;корректно завершить HTTP-сервер: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">:=</span> <span class="token operator">&lt;-</span>serverErrors<span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token operator">&amp;&amp;</span> <span class="token operator">!</span>errors<span class="token punctuation">.</span><span class="token function">Is</span><span class="token punctuation">(</span>err<span class="token punctuation">,</span> http<span class="token punctuation">.</span>ErrServerClosed<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;HTTP-сервер после shutdown: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	logger<span class="token punctuation">.</span><span class="token function">Info</span><span class="token punctuation">(</span><span class="token string">&quot;HTTP-сервер остановлен&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">return</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Канал <code>serverErrors</code> имеет буфер <code>1</code>, поэтому goroutine может сообщить о раннем завершении сервера, даже если <code>serve</code> в этот момент ещё создаёт context сигналов. Контекст shutdown намеренно создаётся от <code>context.Background()</code>: root context уже отменён сигналом, а серверу нужно получить отдельное время, чтобы завершить текущую работу.</p><h2 id="закрытие-зависимостеи" tabindex="-1"><a class="header-anchor" href="#закрытие-зависимостеи"><span>Закрытие зависимостей</span></a></h2><p>HTTP-сервер — не единственный ресурс. Файлы, базы данных и сетевые клиенты тоже могут требовать закрытия. Опишем минимальный интерфейс:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">type</span> Closer <span class="token keyword">interface</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token function">Close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token builtin">error</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">closeAll</span><span class="token punctuation">(</span>closers <span class="token operator">...</span>Closer<span class="token punctuation">)</span> <span class="token builtin">error</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">var</span> closeErr <span class="token builtin">error</span></span>
<span class="line">	<span class="token keyword">for</span> <span class="token boolean">_</span><span class="token punctuation">,</span> closer <span class="token operator">:=</span> <span class="token keyword">range</span> closers <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">if</span> closer <span class="token operator">==</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">			<span class="token keyword">continue</span></span>
<span class="line">		<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">		<span class="token keyword">if</span> err <span class="token operator">:=</span> closer<span class="token punctuation">.</span><span class="token function">Close</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">			closeErr <span class="token operator">=</span> errors<span class="token punctuation">.</span><span class="token function">Join</span><span class="token punctuation">(</span>closeErr<span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">		<span class="token punctuation">}</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">return</span> closeErr</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>В следующей главе <code>*sql.DB</code> станет одной из таких зависимостей. Вызывайте <code>closeAll</code> после <code>server.Shutdown</code>, чтобы не закрыть ресурс, пока активный handler ещё выполняет запрос.</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">if</span> err <span class="token operator">:=</span> <span class="token function">closeAll</span><span class="token punctuation">(</span>database<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;закрыть зависимости: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>errors.Join</code> сохраняет все ошибки закрытия. Не вызывайте <code>os.Exit</code> внутри <code>defer</code>: deferred-функции не выполнятся, а ресурсы могут остаться незакрытыми.</p><h2 id="health-check" tabindex="-1"><a class="header-anchor" href="#health-check"><span>Health-check</span></a></h2><p>Базовый endpoint уже существует:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">router<span class="token punctuation">.</span><span class="token function">GET</span><span class="token punctuation">(</span><span class="token string">&quot;/healthz&quot;</span><span class="token punctuation">,</span> api<span class="token punctuation">.</span>health<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Пока у Task Manager нет базы данных, он может отвечать:</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span><span class="token property">&quot;status&quot;</span><span class="token operator">:</span><span class="token string">&quot;ok&quot;</span><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Health-check должен быть быстрым, не требовать авторизации и не выполнять тяжёлую работу. В Docker и CI он подтвердит, что HTTP-сервер начал отвечать. После подключения PostgreSQL отдельно определим readiness-check, который проверяет критические зависимости; не превращайте простой liveness endpoint в медленный запрос к каждой внешней системе.</p><h2 id="проверка-вручную" tabindex="-1"><a class="header-anchor" href="#проверка-вручную"><span>Проверка вручную</span></a></h2><p>Создайте <code>.env</code> на основе <code>.env.example</code>, затем запустите приложение:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line">go run <span class="token builtin class-name">.</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>В другом терминале:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">curl</span> <span class="token parameter variable">-i</span> http://localhost:8080/healthz</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Вернитесь в первый терминал и нажмите Ctrl+C. В логах должны появиться начало и завершение graceful shutdown. Сервер больше не принимает новые запросы, а процесс завершится с кодом <code>0</code>, если ошибок не было.</p><h2 id="частые-ошибки" tabindex="-1"><a class="header-anchor" href="#частые-ошибки"><span>Частые ошибки</span></a></h2><h3 id="читать-env-внутри-handler" tabindex="-1"><a class="header-anchor" href="#читать-env-внутри-handler"><span>Читать env внутри handler</span></a></h3><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>api <span class="token operator">*</span>API<span class="token punctuation">)</span> <span class="token function">createTask</span><span class="token punctuation">(</span>c <span class="token operator">*</span>gin<span class="token punctuation">.</span>Context<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	baseURL <span class="token operator">:=</span> os<span class="token punctuation">.</span><span class="token function">Getenv</span><span class="token punctuation">(</span><span class="token string">&quot;PRIORITY_SERVICE_URL&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token comment">// ...</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Это повторяет работу на каждом request, скрывает некорректную конфигурацию до первого вызова и усложняет тесты. Читайте config один раз при старте.</p><h3 id="коммитить-env" tabindex="-1"><a class="header-anchor" href="#коммитить-env"><span>Коммитить <code>.env</code></span></a></h3><p><code>.env</code> часто содержит токены и пароли. Коммитьте только <code>.env.example</code> с безопасными примерами и добавьте настоящий <code>.env</code> в <code>.gitignore</code>.</p><h3 id="игнорировать-ошибку-listenandserve" tabindex="-1"><a class="header-anchor" href="#игнорировать-ошибку-listenandserve"><span>Игнорировать ошибку <code>ListenAndServe</code></span></a></h3><p>Если порт занят, сервер не запустится. Проверяйте ошибку и отличайте ожидаемый <code>http.ErrServerClosed</code> после shutdown от настоящей ошибки старта.</p><h3 id="использовать-context-background-для-каждого-вызова" tabindex="-1"><a class="header-anchor" href="#использовать-context-background-для-каждого-вызова"><span>Использовать <code>context.Background()</code> для каждого вызова</span></a></h3><p>В <code>main</code> background — корень жизненного цикла. Но внутри handler передавайте <code>r.Context()</code> или <code>c.Request.Context()</code>, иначе отмена клиента не остановит внешние запросы и SQL-операции.</p><h3 id="закрыть-базу-до-http-сервера" tabindex="-1"><a class="header-anchor" href="#закрыть-базу-до-http-сервера"><span>Закрыть базу до HTTP-сервера</span></a></h3><p>Активный handler может ещё работать с БД. Сначала вызовите <code>server.Shutdown</code>, затем закрывайте зависимости.</p><h2 id="дальше" tabindex="-1"><a class="header-anchor" href="#дальше"><span>Дальше</span></a></h2><p>Task Manager умеет получать проверенную конфигурацию и корректно останавливаться. Далее упакуем приложение и локальный PostgreSQL в Docker Compose, чтобы следующие SQL-упражнения работали в воспроизводимом окружении.</p>`,94)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};